function fieldsHtml(item, isTask) {
    var _isOverdue = false;
    if (item.date_to && item.status !== 'done') {
        var _today = window.__trkState && window.__trkState.today ? window.__trkState.today : '';
        if (_today && item.date_to < _today) _isOverdue = true;
    }
    var _cardCls = 'hyp-fields' + (_isOverdue ? ' hyp-overdue' : '');
    return '<div class="' + _cardCls + '">'
        + '<div class="hyp-row"><input type="text" class="hyp-fld" data-k="title" maxlength="200" placeholder="' + (isTask ? 'Название задания *' : 'Название гипотезы *') + '" value="' + esc(item.title) + '"></div>'
        + '<div class="hyp-row"><textarea class="hyp-fld" data-k="description" rows="2" maxlength="4000" placeholder="Описание">' + esc(item.description) + '</textarea></div>'
        + '<div class="hyp-row hyp-dates">'
        +   '<label>С <input type="date" class="hyp-fld" data-k="date_from" value="' + esc(item.date_from) + '"></label>'
        +   '<label>По <input type="date" class="hyp-fld" data-k="date_to" value="' + esc(item.date_to) + '"></label>'
        +   '<div class="hyp-st-group">'
        +     '<button type="button" class="hyp-st-btn planned ' + (item.status === 'planned' ? 'active' : '') + '" data-st="planned" title="Планируется">⏳</button>'
        +     '<button type="button" class="hyp-st-btn in_progress ' + (item.status === 'in_progress' ? 'active' : '') + '" data-st="in_progress" title="В работе">🔄</button>'
        +     '<button type="button" class="hyp-st-btn done ' + (item.status === 'done' ? 'active' : '') + '" data-st="done" title="Выполнено">✅</button>'
        +     '<button type="button" class="hyp-st-btn failed ' + (item.status === 'failed' ? 'active' : '') + '" data-st="failed" title="Не подтверждено">❌</button>'
        +   '</div>'
        + '</div>'
        + (function(){
            var _asgNames = '';
            if (item.assignees && item.assignees.length) {
                var _st = window.__trkState || {};
                var _emps = _st.employees || [];
                var _names = [];
                item.assignees.slice(0, 3).forEach(function(id) {
                    var e = _emps.find(function(x){ return x.id === id; });
                    if (e) _names.push(e.name.split(' ')[0]);
                });
                if (item.assignees.length > 3) _names.push('+' + (item.assignees.length - 3));
                _asgNames = '<span class="hyp-asg-names">' + esc(_names.join(', ')) + '</span>';
            }
            return '<details class="hyp-people-details"><summary class="hyp-people-label">👥 Ответственные ' + _asgNames + ' <span class="hyp-people-count">' + ((item.assignees && item.assignees.length) || 0) + '</span></summary>' + peopleHtml(item) + '</details>';
        })()
        + '</div>';
}

