        +   '</div>'
        + '</div>'
        + (function(){
            var _asgNames = '';
            if (item.assignees && item.assignees.length) {
                var _st = window.__trkState || {};
                var _emps = _st.employees || [];
                var _names = [];
                item.assignees.forEach(function(id) {
                    var e = _emps.find(function(x){ return x.id === id; });
                    if (e) _names.push(e.name.split(' ')[0] + ' ' + (e.name.split(' ')[1] ? e.name.split(' ')[1][0] + '.' : ''));
